# Run a .ps1 script with explicit UTF-8 read (PS 5.1 -File may misparse no-BOM or mojibake).
# Prefer Python for scripts with heavy Chinese; use this only when PS is required.
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string]$Path,
    [Parameter(ValueFromRemainingArguments = $true)]
    [object[]]$ScriptArgs
)

$ErrorActionPreference = 'Stop'

. (Join-Path $env:USERPROFILE '.ai-workspace\scripts\ensure-utf8-console.ps1')

$resolved = Resolve-Path -LiteralPath $Path
$bytes = [System.IO.File]::ReadAllBytes($resolved.Path)

if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
    $content = [System.Text.Encoding]::UTF8.GetString($bytes, 3, $bytes.Length - 3)
}
else {
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
}

if ($content -match '[\uE000-\uF8FF]' -or $content -match 'â€|ï¿|鍌|椤圭洰|浜ч') {
    Write-Error @"
PS1 script appears to contain mojibake (corrupted Chinese). Do not retry encoding hacks.
Fix: rewrite script in Python, or regenerate .ps1 via Write-Utf8BomFile.
Verify: verify-ps1-script-encoding.ps1 -Path '$($resolved.Path)'
"@
}

$scriptBlock = [ScriptBlock]::Create($content)
if ($ScriptArgs -and $ScriptArgs.Count -gt 0) {
    & $scriptBlock @ScriptArgs
}
else {
    & $scriptBlock
}

# Pre-flight check for Agent-written .ps1 with Chinese content.
param(
