function Add-Warn([string]$Msg) { $script:warnings += $Msg }

if (-not (Test-Path -LiteralPath $Path)) {
    Add-Fail "File not found: $Path"
    Write-Output "FAIL: verify-ps1-script-encoding"
    $failures | ForEach-Object { Write-Output "  - $_" }
    exit 1
}

$bytes = [System.IO.File]::ReadAllBytes((Resolve-Path -LiteralPath $Path).Path)
$hasBom = ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF)

if ($hasBom) {
    $content = [System.Text.Encoding]::UTF8.GetString($bytes, 3, $bytes.Length - 3)
    Write-Output 'OK: UTF-8 BOM present'
}
else {
    $content = [System.Text.Encoding]::UTF8.GetString($bytes)
    if ($content -match '[\u4e00-\u9fff]') {
        Add-Fail 'Non-ASCII Chinese without UTF-8 BOM — PS 5.1 -File will misparse; rewrite via Write-Utf8BomFile or use Python'
    }
    else {
        Write-Output 'OK: ASCII-only script (no BOM required)'
    }
}

$mojibakePatterns = @(
    'â€',
    'ï¿',
    '鍌',
    '椤圭洰',
    '浜ч',
    '鏅鸿',
    '鍦烘櫙'
)
$hits = @($mojibakePatterns | Where-Object { $content -match [regex]::Escape($_) })
if ($hits.Count -ge 2) {
    Add-Fail "Likely mojibake in script (patterns: $($hits -join ', ')). Agent must rewrite in Python, not patch encoding."
}
elseif ($hits.Count -eq 1) {
    Add-Warn "Possible mojibake pattern: $($hits[0])"
}

if ($warnings.Count -gt 0) {
    Write-Output 'WARNINGS:'
    $warnings | ForEach-Object { Write-Output "  - $_" }
}

if ($failures.Count -gt 0) {
    Write-Output 'FAILURES:'
    $failures | ForEach-Object { Write-Output "  - $_" }
    Write-Output ''
    Write-Output 'Agent rule: use Python for Office/Chinese automation; do not retry chcp/escape loops.'
    exit 1
}

Write-Output 'PASS: verify-ps1-script-encoding'
exit 0

