#!/usr/bin/env python3
"""Print a text file as UTF-8. Agent substitute for Get-Content (no RTK/PS cmdlet)."""
from __future__ import annotations

import sys
from pathlib import Path


def main() -> int:
    if len(sys.argv) < 2:
        print("usage: read-text-file.py <path>", file=sys.stderr)
        return 1
    path = Path(sys.argv[1])
    if not path.is_file():
        print(f"not found: {path}", file=sys.stderr)
        return 1
    raw = path.read_bytes()
    if raw.startswith(b"\xef\xbb\xbf"):
        text = raw[3:].decode("utf-8")
    else:
        text = raw.decode("utf-8")
    sys.stdout.write(text)
    if not text.endswith("\n"):
        sys.stdout.write("\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

# Run a .py file with the agent Python (never inline python -c for multi-line/CJK).
param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string]$ScriptPath,
    [Parameter(ValueFromRemainingArguments = $true)]
    [object[]]$ScriptArgs
)

$ErrorActionPreference = 'Stop'

$envJson = Join-Path $env:USERPROFILE '.ai-workspace\runtime\python-env.json'
$python = $null
if (Test-Path -LiteralPath $envJson) {
    $info = Get-Content -LiteralPath $envJson -Raw -Encoding UTF8 | ConvertFrom-Json
    if ($info.python -and (Test-Path -LiteralPath $info.python)) {
        $python = $info.python
    }
}
if (-not $python) {
    $python = (Get-Command python -ErrorAction SilentlyContinue).Source
}
if (-not $python) {
    Write-Error 'No python found. Run ensure-python-env.ps1 first.'
}

$resolved = Resolve-Path -LiteralPath $ScriptPath
if ($ScriptArgs -and $ScriptArgs.Count -gt 0) {
    & $python $resolved.Path @ScriptArgs
}
else {
    & $python $resolved.Path
}
exit $LASTEXITCODE

# Report which Python/packages agents should use (ASCII-only output).
param([switch]$Quiet)

$ErrorActionPreference = 'SilentlyContinue'
$ensure = Join-Path $PSScriptRoot 'ensure-python-env.ps1'
if (Test-Path -LiteralPath $ensure) {
    & $ensure -Quiet | Out-Null
}

$envJson = Join-Path $env:USERPROFILE '.ai-workspace\runtime\python-env.json'
$python = $null
$source = 'none'
if (Test-Path -LiteralPath $envJson) {
    $info = Get-Content -LiteralPath $envJson -Raw -Encoding UTF8 | ConvertFrom-Json
    $python = $info.python
    $source = $info.source
}

$codexPy = Join-Path $env:USERPROFILE '.cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe'
$failures = @()
$warnings = @()

function Add-Fail([string]$m) { $script:failures += $m }
function Add-Warn([string]$m) { $script:warnings += $m }
function Write-Line([string]$m) { if (-not $Quiet) { Write-Host $m } }

if (-not $python) { Add-Fail 'No agent python in python-env.json' }
else { Write-Line "OK: agent python=$python ($source)" }

if (Test-Path -LiteralPath $codexPy) {
    Write-Line "NOTE: codex bundled python=$codexPy (no win32com - do NOT use for Office COM)"
}

